INSERT INTO especies (id, nombre_cientifico, nombre_comun, nombre_gbif, gbif_taxon_key, tipo_fotosintesis, tasa_r_base, capacidad_k_base, altura_max_m, luz_optima, agua_optima, temp_optima, nutrientes_optimos, ph_optimo, co2_optimo, dias_madurez, color_hex, descripcion) VALUES
(1, 'Agave tequilana Weber', 'Agave Azul (Tequilero)', 'Agave tequilana', 2766899, 'CAM', 0.140, 4500.00, 3.80, 65.0, 48.0, 22.0, 63.0, 6.8, 425.0, 2555, '#4a858c', 'Variedad oficial para tequila (DOT). Muy sensible a heladas: daño desde 0 °C y muerte cerca de -6 °C. Óptimo térmico 18-26 °C de media.'),
(2, 'Agave angustifolia Haw', 'Agave Espadín (Mezcalero)', 'Agave angustifolia', 2766846, 'CAM', 0.165, 5200.00, 4.20, 68.0, 42.0, 25.0, 55.0, 7.0, 425.0, 2190, '#5c9c54', 'Especie de amplia distribución (Sonora a Centroamérica), la más tolerante al calor y al déficit hídrico del catálogo.'),
(3, 'Agave salmiana Otto', 'Maguey Pulquero / Manso', 'Agave salmiana', 2766660, 'CAM', 0.120, 6800.00, 4.80, 63.0, 50.0, 18.0, 68.0, 7.1, 425.0, 3285, '#28593a', 'Agave de gran porte del Altiplano (2000-2800 m). Soporta heladas moderadas (daño desde -4 °C) y suelos más pesados.'),
(4, 'Agave cupreata Trel', 'Agave Papalote', 'Agave cupreata', 2766892, 'CAM', 0.110, 3800.00, 3.10, 60.0, 53.0, 20.0, 63.0, 6.4, 425.0, 2920, '#738c4a', 'Especie silvestre de laderas de la Depresión del Balsas (1200-1850 m, ~19 °C, ~960 mm). Sensible al calor extremo.'),
(5, 'Arabidopsis thaliana', 'Arabidopsis (Modelo Genético)', 'Arabidopsis thaliana', 3052436, 'C3', 0.250, 850.00, 1.20, 50.0, 63.0, 21.0, 68.0, 6.5, 425.0, 45, '#76b843', 'Organismo modelo C3 de ciclo corto usado como control (no es agave): poco tolerante a sequía y calor.');
